function fixedWindow(limit, windowMs) {
  const counts = new Map();
  return (now) => {
    const start = Math.floor(now / windowMs) * windowMs;
    const count = counts.get(start) ?? 0;
    if (count >= limit) return false;
    counts.set(start, count + 1);
    return true;
  };
}

