function fixedWindow({ limit, windowMs }) {
  const windows = new Map();
  return (key, now) => {
    const start = Math.floor(now / windowMs) * windowMs;
    let w = windows.get(key);
    if (!w || w.start !== start) {
      w = { start, count: 0 };
      windows.set(key, w);
    }
    if (w.count >= limit) return { allowed: false, retryAfterMs: start + windowMs - now };
    w.count++;
    return { allowed: true, remaining: limit - w.count };
  };
}

const check = fixedWindow({ limit: 2, windowMs: 1000 });
