function tokenBucket({ capacity, refillPerSecond }) {
  const buckets = new Map();
  return (key, now, cost = 1) => {
    const b = buckets.get(key) ?? { tokens: capacity, at: now };
    b.tokens = Math.min(capacity, b.tokens + ((now - b.at) / 1000) * refillPerSecond);
    b.at = now;
    buckets.set(key, b);
    if (b.tokens < cost) return { allowed: false, retryAfterMs: Math.ceil(((cost - b.tokens) / refillPerSecond) * 1000) };
    b.tokens -= cost;
    return { allowed: true, remaining: Math.floor(b.tokens) };
  };
}

