function slidingLog({ limit, windowMs }) {
  const logs = new Map();
  return (key, now) => {
    const log = (logs.get(key) ?? []).filter((t) => t > now - windowMs);
    logs.set(key, log);
    if (log.length >= limit) return { allowed: false, retryAfterMs: log[0] + windowMs - now };
    log.push(now);
    return { allowed: true, remaining: limit - log.length };
  };
}

const check = slidingLog({ limit: 2, windowMs: 1000 });
