function toResponse(decision) {
  if (decision.allowed) return { status: 200, headers: { "X-RateLimit-Remaining": String(decision.remaining) } };
  const seconds = Math.max(1, Math.ceil(decision.retryAfterMs / 1000));
  return { status: 429, headers: { "Retry-After": String(seconds) } };
}

