function createStore() {
  const counts = new Map();
  return {
    incr(key) {
      const next = (counts.get(key) ?? 0) + 1;
      counts.set(key, next);
      return next;
    },
  };
}

function makeInstance(store, limit) {
  return (key) => store.incr(key) <= limit;
}

const store = createStore();
const instances = [makeInstance(store, 4), makeInstance(store, 4), makeInstance(store, 4)];
let allowed = 0;
